CREATE TABLE P360_INVENTORY_OPS (ID VARCHAR2(80) PRIMARY KEY, ORDER_ID NUMBER(19) NOT NULL REFERENCES P360_ORDERS(ID), ACTION VARCHAR2(20) NOT NULL, COMPLETED BOOLEAN NOT NULL, UPDATED_AT TIMESTAMP WITH TIME ZONE NOT NULL, LAST_ERROR VARCHAR2(200));
CREATE INDEX IDX_INVENTORY_ORDER ON P360_INVENTORY_OPS(ORDER_ID);
